const raw = $input.first().json;
const body = raw.body ?? raw;
const eventType = raw.headers?.["x-github-event"];

// ping — подтверждение регистрации webhook'а: не PR-событие,
// отвечаем 200, чтобы GitHub не считал доставку неудачной
if (eventType === "ping") {
  return [{ json: { skip: true, reason: "ping acknowledged" } }];
}

const owner = body.repository?.owner?.login;
const repo = body.repository?.name;
const pullNumber = body.number;
const headSha = body.pull_request?.head?.sha;
const action = body.action;

const missing = [];
if (!owner) missing.push("repository.owner.login");
if (!repo) missing.push("repository.name");
if (!pullNumber) missing.push("number");
if (!headSha) missing.push("pull_request.head.sha");
if (missing.length > 0) {
  throw new Error(
    `Webhook payload is missing required fields: ${missing.join(", ")}. ` +
    `Refusing to guess: this workflow must only run on real PR events.`
  );
}

return [{
  json: { action, owner, repo, pull_number: pullNumber, head_sha: headSha }
}];

// Tool: scan_diff — детерминированный сканер секретов
const input = $input.first().json;

// Аргументы от агента могут прийти объектом или JSON-строкой в query
let args = input.query ?? input;
if (typeof args === "string") {
  try {
    args = JSON.parse(args);
  } catch (error) {
    throw new Error(`scan_diff: cannot parse arguments as JSON: ${error.message}`);
  }
}

// Нормализация входа: files|diff, filename|path, added_lines: string[] | {line, content}[]
const rawFiles = args.files ?? args.diff ?? [];
if (!Array.isArray(rawFiles) || rawFiles.length === 0) {
  throw new Error(
    "scan_diff: expected a non-empty array 'files' of {filename, added_lines}"
  );
}

const files = rawFiles.map((f) => ({
  path: f.path ?? f.filename ?? "unknown",
  added_lines: (f.added_lines ?? []).map((l) =>
    typeof l === "string" ? l : (l.content ?? String(l))
  ),
}));

const rules = [
  { id: "private-key", re: /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/, severity: "block" },
  { id: "github-token", re: /\b(?<val>ghp_[A-Za-z0-9]{20,})\b/, severity: "block" },
  { id: "aws-access-key", re: /\b(?<val>AKIA[0-9A-Z]{16})\b/, severity: "block" },
  { id: "stripe-like-live-key", re: /\b(?<val>sk-live-[A-Za-z0-9_-]{8,})\b/, severity: "block" },
  {
    id: "generic-secret-assignment",
    re: /\b(?<name>[\w-]*(?:password|secret|token|api[_-]?key)[\w-]*)\s*[:=]\s*(?:"(?<dq>[^"]{6,})"|'(?<sq>[^']{6,})'|(?<bare>[^\s#]{6,}))/i,
    severity: "warn",
  },
  { id: "connection-string-password", re: /\b(?:password|pwd)\s*=\s*(?<val>[^; \n]+)/i, severity: "warn" },
];

function maskValue(s) {
  if (s.length <= 10) return "***";
  return s.slice(0, 4) + "***" + s.slice(-3);
}

const findings = [];

for (const file of files) {
  file.added_lines.forEach((line, idx) => {
    for (const rule of rules) {
      const m = line.match(rule.re);
      if (!m) continue;

      const value =
        m.groups?.val ?? m.groups?.dq ?? m.groups?.sq ?? m.groups?.bare ?? m[0];
      const maskedValue = maskValue(value);

      findings.push({
        rule_id: rule.id,
        path: file.path,
        line_number_in_added_block: idx + 1,
        matched_masked: maskedValue,
        line_preview: line.replace(value, maskedValue).slice(0, 200),
        severity: rule.severity,
      });
      break;
    }
  });
}

return JSON.stringify({ findings_count: findings.length, findings }, null, 2);
